54	/*!
55	    \brief      send a byte through the SPI interface and return a byte received from the SPI bus
56	    \param[in]  byte: data to be send
57	    \param[out] none
58	    \retval     the value of the received byte
59	*/
60	static uint8_t spi_write_byte(uint8_t byte)
61	{
62	    while(RESET == (SPI_STAT&SPI_FLAG_TBE));
63	    SPI_DATA = byte;
64	
65	    while(RESET == (SPI_STAT&SPI_FLAG_RBNE));
66	    return(SPI_DATA);
67	} 
